def runfit(G):
    cols=[np.ones_like(t),G,P,P**2,P**3,P*G,P**2*G,P**3*G,P*t,t,t*G,P*G*t]
    A=np.array(cols).T
    c,*_=np.linalg.lstsq(A,dP_dt,rcond=None)
    r=dP_dt-A@c
    return np.mean(r**2)/np.var(dP_dt)
